-- 0001_init.sql — Insight D1 schema (migration 0001).
--
-- D1 IS METADATA ONLY (INV-T5).
-- This database stores accounts, projects, config and access control.
-- It MUST NOT contain any telemetry data-point store (no per-reading rows,
-- no "readings" / "telemetry_points" / "samples" tables). Time-series
-- samples live in the analytics/data plane, never in D1.
--
-- Conventions:
--   * ids            -> TEXT (ULID/UUID generated by the application)
--   * timestamps     -> INTEGER epoch milliseconds (Unix ms, UTC)
--   * booleans       -> INTEGER 0/1
--   * secret material-> stored as hashes only, never plaintext

-- ---------------------------------------------------------------------------
-- schema_version — migration guard table (single row, holds applied version).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS schema_version (
  id          INTEGER PRIMARY KEY CHECK (id = 1),
  version     INTEGER NOT NULL,
  applied_at  INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_schema_version_version
  ON schema_version (version);

-- Seed the guard row: no migration applied yet (version 0).
INSERT OR IGNORE INTO schema_version (id, version, applied_at) VALUES (1, 0, 0);

-- ---------------------------------------------------------------------------
-- users — platform identities (humans).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
  id             TEXT PRIMARY KEY,
  email          TEXT NOT NULL,
  email_verified INTEGER NOT NULL DEFAULT 0,
  name           TEXT,
  image          TEXT,
  password_hash  TEXT,
  created_at     INTEGER NOT NULL,
  updated_at     INTEGER NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_users_email
  ON users (email);

-- ---------------------------------------------------------------------------
-- accounts — linked auth providers / credentials for a user.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS accounts (
  id                       TEXT PRIMARY KEY,
  user_id                  TEXT NOT NULL,
  provider                 TEXT NOT NULL,
  provider_account_id      TEXT NOT NULL,
  type                     TEXT NOT NULL,
  access_token             TEXT,
  refresh_token            TEXT,
  access_token_expires_at  INTEGER,
  refresh_token_expires_at INTEGER,
  scope                    TEXT,
  id_token                 TEXT,
  session_state            TEXT,
  password_hash            TEXT,
  created_at               INTEGER NOT NULL,
  updated_at               INTEGER NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_accounts_provider_account
  ON accounts (provider, provider_account_id);

CREATE INDEX IF NOT EXISTS idx_accounts_user_id
  ON accounts (user_id);

-- ---------------------------------------------------------------------------
-- sessions — active login sessions.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sessions (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL,
  token_hash TEXT NOT NULL,
  user_agent TEXT,
  ip_address TEXT,
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_sessions_token_hash
  ON sessions (token_hash);

CREATE INDEX IF NOT EXISTS idx_sessions_user_id
  ON sessions (user_id);

CREATE INDEX IF NOT EXISTS idx_sessions_expires_at
  ON sessions (expires_at);

-- ---------------------------------------------------------------------------
-- verifications — short-lived verification challenges (OTP / magic link).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS verifications (
  id         TEXT PRIMARY KEY,
  identifier TEXT NOT NULL,
  value_hash TEXT NOT NULL,
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_verifications_identifier
  ON verifications (identifier);

CREATE INDEX IF NOT EXISTS idx_verifications_expires_at
  ON verifications (expires_at);

-- ---------------------------------------------------------------------------
-- projects — the top-level tenant / namespace for devices and telemetry.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS projects (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  slug        TEXT NOT NULL,
  description TEXT,
  owner_id    TEXT NOT NULL,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL,
  FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_projects_slug
  ON projects (slug);

CREATE INDEX IF NOT EXISTS idx_projects_owner_id
  ON projects (owner_id);

-- ---------------------------------------------------------------------------
-- project_members — user membership/role within a project.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS project_members (
  id         TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  user_id    TEXT NOT NULL,
  role       TEXT NOT NULL DEFAULT 'viewer',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_project_members_project_user
  ON project_members (project_id, user_id);

CREATE INDEX IF NOT EXISTS idx_project_members_user_id
  ON project_members (user_id);

-- ---------------------------------------------------------------------------
-- project_tokens — machine/API credentials for a project.
-- The secret is stored ONLY as a hash, never in plaintext.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS project_tokens (
  id          TEXT PRIMARY KEY,
  project_id  TEXT NOT NULL,
  name        TEXT NOT NULL,
  token_hash  TEXT NOT NULL,
  token_prefix TEXT,
  scopes      TEXT,
  last_used_at INTEGER,
  expires_at  INTEGER,
  revoked_at  INTEGER,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL,
  FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_project_tokens_token_hash
  ON project_tokens (token_hash);

CREATE INDEX IF NOT EXISTS idx_project_tokens_project_id
  ON project_tokens (project_id);

CREATE INDEX IF NOT EXISTS idx_project_tokens_expires_at
  ON project_tokens (expires_at);

-- ---------------------------------------------------------------------------
-- project_variables — per-project configuration key/value pairs.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS project_variables (
  id          TEXT PRIMARY KEY,
  project_id  TEXT NOT NULL,
  key         TEXT NOT NULL,
  value       TEXT,
  is_secret   INTEGER NOT NULL DEFAULT 0,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL,
  FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_project_variables_project_key
  ON project_variables (project_id, key);

CREATE INDEX IF NOT EXISTS idx_project_variables_project_id
  ON project_variables (project_id);
